#!/usr/bin/env python3
"""No-op checker for a read-only, free-text response task."""

import sqlite3
from pathlib import Path


def target_records_are_present(workspace: Path):
    """Diagnostic helper; this task's scored criteria are intentionally LLM-routed."""
    db = workspace.parent / "system" / "tue_operations_intake" / "state.db"
    if not db.exists():
        return {"score": 0, "detail": "intake database unavailable"}
    with sqlite3.connect(db) as connection:
        request = connection.execute(
            "SELECT COUNT(*) FROM intake_requests WHERE intake_id=? AND case_id=?",
            ("INT-2024-0731-0042", "RFP-2024-000731"),
        ).fetchone()[0]
        rows = connection.execute(
            "SELECT COUNT(*) FROM intake_rework_items WHERE intake_id=? AND rework_reason_code=? AND validation_status=?",
            ("INT-2024-0731-0042", "MISSING_SUPERVISOR_APPROVAL", "validated"),
        ).fetchone()[0]
    score = int(request == 1 and rows == 2)
    return {"score": score, "detail": f"request_rows={request}, validated_history_rows={rows}"}
